WITH base AS (SELECT *, CEIL(amount) amount_whole FROM transactions WHERE is_flagged), agg AS (SELECT CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END txn_cohort, MAX(txn_time) latest_txn_time FROM base GROUP BY CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM agg ORDER BY txn_cohort DESC, latest_txn_time;
